/* A raised key on any surface: a light fill, a hairline edge and a darker
   bottom lip, so it reads as something pressed, not a badge. */
.kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--kbd-radius, var(--r-2xs));
  background: var(--kbd-bg, rgba(var(--rgb-white), 0.8));
  box-shadow:
    inset 0 0 0 var(--border-w) var(--line),
    inset 0 -1px 0 rgba(var(--rgb-brand-deep), 0.14),
    0 1px 1px rgba(var(--rgb-contact), 0.06);
  font-family: var(--font-body);
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1;
  color: var(--kbd-ink, var(--ink-secondary));
  white-space: nowrap;
}

.md {
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  font-size: var(--text-caption);
}

.sm {
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  font-size: var(--text-micro);
}

.group {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-family: var(--font-body);
}

.separator {
  font-size: var(--text-caption);
  color: var(--ink-muted);
}

import { Fragment, type HTMLAttributes, type ReactNode } from "react";
import { cx } from "../_internal/cx";
import styles from "./Kbd.module.css";

export type KbdProps = HTMLAttributes<HTMLElement> & {
  children: ReactNode;
  /** sm sits inside menus and tooltips; md in running text. */
  size?: "sm" | "md";
};

/** One keyboard key, as a small raised key cap. Renders a real <kbd>. */
export function Kbd({ children, size = "md", className, ...rest }: KbdProps) {
  return (
    <kbd data-slot="kbd" className={cx(styles.kbd, styles[size], className)} {...rest}>
      {children}
    </kbd>
  );
}

export type KbdGroupProps = {
  /** The keys pressed together, in order: ["Ctrl", "K"]. */
  keys: ReadonlyArray<string>;
  /** Between the keys. Defaults to a muted "+". */
  separator?: ReactNode;
  size?: "sm" | "md";
  className?: string;
};

/**
 * A key combination. The outer <kbd> wraps one <kbd> per key, which is how
 * HTML marks up a chord, so a screen reader reads it as one input.
 */
export function KbdGroup({ keys, separator = "+", size = "md", className }: KbdGroupProps) {
  return (
    <kbd data-slot="kbd-group" className={cx(styles.group, className)}>
      {keys.map((k, i) => (
        <Fragment key={`${k}-${i}`}>
          {i ? (
            <span className={styles.separator} aria-hidden="true">
              {separator}
            </span>
          ) : null}
          <kbd className={cx(styles.kbd, styles[size])}>{k}</kbd>
        </Fragment>
      ))}
    </kbd>
  );
}
